import json, csv
from jsonschema import validate, ValidationError

def run_case(client, prompt_template, case, schema):
    """Run one case and return a dict of mechanical pass/fail checks."""
    raw = client.complete(prompt_template.format(review=case["input"]))
    result = {"id": case["id"], "tokens": raw.usage.input + raw.usage.output}

    # Check 1: parses and validates. Free.
    try:
        data = json.loads(raw.text)
        validate(data, schema)
        result["schema_valid"] = True
    except (json.JSONDecodeError, ValidationError):
        return {**result, "schema_valid": False}

    # Check 2: every quote is verbatim from the input. Free.
    result["quotes_verbatim"] = all(
        issue["quote"] in case["input"] for issue in data.get("issues", [])
    )
    # Check 3: labels come from the allowed set. Free.
    result["labels_valid"] = all(
        issue["category"] in schema["$defs"]["category"]["enum"]
        for issue in data.get("issues", [])
    )
    # Check 4: matches the human label. Needs your one-time labelling.
    result["sentiment_correct"] = data["sentiment"] == case["expected_sentiment"]
    return result

def run_suite(client, variants, cases, schema, runs=3, out="results.csv"):
    rows = [
        {**run_case(client, tmpl, case, schema), "variant": name, "run": r}
        for name, tmpl in variants.items()
        for r in range(runs)          # repeat runs: variance is data, not noise
        for case in cases
    ]
    with open(out, "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=rows[0].keys())
        w.writeheader(); w.writerows(rows)
    return rows

from jsonschema import validate, ValidationError

def complete_structured(client, prompt, schema, max_repairs=1):
    """Return validated data, or a typed failure. Never raises, never loops."""
    messages = [{"role": "user", "content": prompt}]

    for attempt in range(max_repairs + 1):
        raw = client.complete(messages, response_schema=schema)  # constrained decoding
        try:
            data = json.loads(raw.text)
            validate(data, schema)
            return Ok(data)
        except (json.JSONDecodeError, ValidationError) as e:
            if attempt == max_repairs:
                log.warning("schema_repair_exhausted", error=str(e))
                return Err("schema_validation_failed")   # degrade, don't raise
            # Feed the validation error back in — this is what makes repair work
            messages += [
                {"role": "assistant", "content": raw.text},
                {"role": "user", "content": f"That failed validation: {e}. Return valid JSON only."},
            ]

import random, time

RETRYABLE = {429, 500, 502, 503, 504}   # NOT 400 — a bad request stays bad

def call_with_retry(fn, *, is_mutating: bool, idempotency_key=None,
                    max_attempts=4, timeout=30.0):
    if is_mutating and idempotency_key is None:
        raise ValueError("mutating calls require an idempotency key before retrying")

    for attempt in range(max_attempts):
        try:
            return fn(timeout=timeout, idempotency_key=idempotency_key)
        except HTTPError as e:
            if e.status not in RETRYABLE or attempt == max_attempts - 1:
                raise
            # exponential backoff with jitter: prevents synchronised retry storms
            time.sleep((2 ** attempt) + random.uniform(0, 1))
        except TimeoutError:
            if not is_mutating:
                continue          # safe: no side effect to duplicate
            raise                 # unsafe: the write may have landed. Escalate.

from dataclasses import dataclass
from typing import Protocol, Iterator

@dataclass
class Message:
    role: str          # "user" | "assistant" | "system"
    content: str

@dataclass
class Completion:
    text: str
    input_tokens: int
    output_tokens: int
    model: str         # record which model produced this — you WILL need it

class LLMClient(Protocol):
    """Your call sites depend on this. Never on a vendor SDK."""
    def complete(self, messages: list[Message], *, response_schema=None) -> Completion: ...
    def stream(self, messages: list[Message]) -> Iterator[str]: ...

class AcmeAdapter:                       # one adapter per provider
    def __init__(self, sdk_client, model: str):
        self._sdk, self._model = sdk_client, model

    def complete(self, messages, *, response_schema=None) -> Completion:
        r = self._sdk.messages.create(          # vendor-specific shape lives ONLY here
            model=self._model,
            messages=[{"role": m.role, "content": m.content} for m in messages],
        )
        return Completion(r.content[0].text, r.usage.input_tokens,
                          r.usage.output_tokens, self._model)

ANSWER_SCHEMA = {
    "type": "object",
    "properties": {
        "answer": {"type": ["string", "null"]},          # null is a first-class outcome
        "reason": {"enum": ["answered", "not_covered", "ambiguous"]},
        "claims": {"type": "array", "items": {
            "type": "object",
            "properties": {
                "text":  {"type": "string"},
                "source_id": {"type": "string"},          # must exist in supplied context
                "quote": {"type": "string"},              # must be verbatim from that chunk
            },
            "required": ["text", "source_id", "quote"]}},
    },
    "required": ["answer", "reason", "claims"],
}

def verify_grounding(result, retrieved_chunks):
    """Free checks. No human, no judge model, no reference answer needed."""
    by_id = {c.id: c.text for c in retrieved_chunks}
    problems = []
    for claim in result["claims"]:
        if claim["source_id"] not in by_id:
            problems.append(("fabricated_citation", claim["source_id"]))
        elif claim["quote"] not in by_id[claim["source_id"]]:
            problems.append(("quote_not_verbatim", claim["quote"][:60]))
    if result["reason"] == "answered" and not result["claims"]:
        problems.append(("unsupported_answer", None))     # answered with zero evidence
    return problems

def generate_with_critique(client, task, criteria, max_rounds=2):
    draft = client.complete(GENERATOR_PROMPT.format(task=task))

    for round_n in range(max_rounds):
        # The critic sees: the output, and the criteria. That is all.
        # It does NOT see the generator's prompt, reasoning, or prior critiques —
        # those would re-anchor it on the judgement we are trying to challenge.
        verdict = client.complete(
            CRITIC_PROMPT.format(output=draft.text, criteria=criteria),
            response_schema=CRITIQUE_SCHEMA,     # {passed: bool, violations: [...]}
        )
        if verdict["passed"]:
            return draft, verdict, round_n

        draft = client.complete(
            REVISE_PROMPT.format(output=draft.text, violations=verdict["violations"])
        )

    # Budget exhausted with outstanding violations: escalate, do not ship silently.
    return draft, verdict, max_rounds

import hashlib, random

def curate(examples, house_style_changed_on):
    """Return kept examples plus a record of WHY each was dropped.
    Report these counts — the drop reasons are a finding, not bookkeeping."""
    kept, dropped = [], []
    seen_hashes = set()
    for ex in examples:
        h = hashlib.sha256(ex.output.strip().encode()).hexdigest()
        if ex.created < house_style_changed_on:
            dropped.append((ex.id, "predates_current_format"))
        elif h in seen_hashes:
            dropped.append((ex.id, "duplicate_output"))
        elif not ex.passes_internal_review:
            dropped.append((ex.id, "failed_review"))   # don't teach past mistakes
        else:
            seen_hashes.add(h)
            kept.append(ex)
    return kept, dropped

def split_no_leakage(examples, seed=0):
    """Split on SOURCE DOCUMENT, not on example, so two examples derived from
    the same source can never straddle the train/test boundary."""
    by_source = {}
    for ex in examples:
        by_source.setdefault(ex.source_document_id, []).append(ex)

    sources = sorted(by_source)
    random.Random(seed).shuffle(sources)
    n = len(sources)
    train_s, val_s, test_s = sources[:int(.8*n)], sources[int(.8*n):int(.9*n)], sources[int(.9*n):]
    pick = lambda ss: [e for s in ss for e in by_source[s]]
    return pick(train_s), pick(val_s), pick(test_s)
